variables.input:
timeseries avg(aerospike_node_stats_uptime, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) }), by: { service }
| fields ip = splitString(service, ":")[0]
| summarize n = count(), by: { ip }
| fields ip

5.query:
timeseries value = sum(aerospike_node_stats_client_connections_opened, filter: { in(cluster_name, array($cluster)) }, rate: 1s), by: { cluster_name, service }
| sort arrayAvg(value) desc
| limit 10
| fieldsRename opened = value
| append [
  timeseries value = sum(aerospike_node_stats_client_connections_closed, filter: { in(cluster_name, array($cluster)) }, rate: 1s), by: { cluster_name, service }
  | sort arrayAvg(value) desc
  | limit 10
  | fieldsRename closed = value
]

6.query:
timeseries a = avg(aerospike_latencies_read_ms_bucket, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) and in(ns, array($namespace)) }), by: { le, service }
| append [
  timeseries ops_sec = avg(aerospike_latencies_read_ms_count, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) and in(ns, array($namespace)) }), by: { service }
]

7.query:
timeseries a = avg(aerospike_latencies_write_ms_bucket, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) and in(ns, array($namespace)) }), by: { le, service }
| append [
  timeseries ops_sec = avg(aerospike_latencies_write_ms_count, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) and in(ns, array($namespace)) }), by: { service }
]

8.query:
timeseries a0 = avg(aerospike_node_stats_process_cpu_pct, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) }), a1 = avg(aerospike_node_stats_system_total_cpu_pct, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) }), by: { cluster_name, service }
| fieldsAdd asd = a0[], host = a1[]
| fieldsRemove a0, a1

8.description:
Equivalent Prometheus query:
aerospike_node_stats_process_cpu_pct{job=~"$job_name", cluster_name=~"$cluster", service=~"$node.*", ns=~"$namespace|$^"}
aerospike_node_stats_system_total_cpu_pct{job=~"$job_name", cluster_name=~"$cluster", service=~"$node.*", ns=~"$namespace|$^"}

10.query:
timeseries value = sum(node_disk_written_bytes_total, filter: { in(cluster_name, array($cluster)) }, rate: 1s), by: { cluster_name, device, `service.instance.id` }
| sort arrayAvg(value) desc
| limit 10
| fieldsRename write = value
| append [
  timeseries value = sum(node_disk_read_bytes_total, filter: { in(cluster_name, array($cluster)) }, rate: 1s), by: { cluster_name, device, `service.instance.id` }
  | sort arrayAvg(value) desc
  | limit 10
  | fieldsRename read = value
]

11.query:
timeseries a0 = avg(node_filesystem_avail_bytes, filter: { in(cluster_name, array($cluster)) }), a1 = avg(node_filesystem_size_bytes, filter: { in(cluster_name, array($cluster)) }), by: { cluster_name, device, fstype, mountpoint, `service.instance.id` }
| fieldsAdd a0 = arrayDelta(a0)
| fieldsAdd a0 = a0[] / (interval / 1s)
| fieldsAdd value = ((a0[] * 100) / a1[])
| fieldsRemove a0, a1
| summarize value = avg(value[]), by: { timeframe, interval, `service.instance.id`, device }

12.query:
